CREATE TABLE partners (id TEXT PRIMARY KEY, name TEXT NOT NULL, mission TEXT NOT NULL, profile_version TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE persons (id TEXT PRIMARY KEY, partner_id TEXT NOT NULL REFERENCES partners(id), name TEXT NOT NULL, source TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', permission TEXT NOT NULL DEFAULT '', suppressed INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE channel_identities (id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES persons(id), channel TEXT NOT NULL, account_id TEXT NOT NULL, external_id TEXT NOT NULL, UNIQUE(channel, account_id, external_id));
CREATE TABLE conversations (id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES persons(id), channel_identity_id TEXT REFERENCES channel_identities(id), channel TEXT NOT NULL, ownership TEXT NOT NULL DEFAULT 'AI_OWNED' CHECK(ownership IN ('AI_OWNED','HUMAN_OWNED')), revision INTEGER NOT NULL DEFAULT 0, stage TEXT NOT NULL DEFAULT 'new', created_at TEXT NOT NULL);
CREATE TABLE messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), direction TEXT NOT NULL CHECK(direction IN ('in','out')), author TEXT NOT NULL, text TEXT NOT NULL, external_id TEXT, source TEXT NOT NULL, draft_id TEXT, created_at TEXT NOT NULL, UNIQUE(conversation_id, direction, external_id));
CREATE TABLE facts (id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES persons(id), text TEXT NOT NULL, source_message_id TEXT REFERENCES messages(id), source_ref TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'candidate', author TEXT NOT NULL, run_id TEXT, created_at TEXT NOT NULL);
CREATE TABLE tasks (id TEXT PRIMARY KEY, partner_id TEXT NOT NULL REFERENCES partners(id), conversation_id TEXT REFERENCES conversations(id), kind TEXT NOT NULL, title TEXT NOT NULL, instructions TEXT NOT NULL, due_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', evidence TEXT NOT NULL DEFAULT '', dedupe_key TEXT UNIQUE, author TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX tasks_due ON tasks(status,due_at);
CREATE TABLE runs (id TEXT PRIMARY KEY, partner_id TEXT NOT NULL REFERENCES partners(id), task_id TEXT REFERENCES tasks(id), conversation_id TEXT REFERENCES conversations(id), status TEXT NOT NULL, runtime TEXT NOT NULL, model TEXT NOT NULL, context_json TEXT NOT NULL, result_json TEXT, error TEXT, input_tokens INTEGER, output_tokens INTEGER, estimated_cost_usd REAL, cost_status TEXT NOT NULL DEFAULT 'unknown', created_at TEXT NOT NULL, finished_at TEXT);
CREATE TABLE drafts (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), run_id TEXT REFERENCES runs(id), action TEXT NOT NULL DEFAULT 'reply', reason TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending', context_revision INTEGER NOT NULL, current_version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE UNIQUE INDEX one_active_draft ON drafts(conversation_id) WHERE status IN ('pending','approved','sending');
CREATE TABLE draft_versions (id TEXT PRIMARY KEY, draft_id TEXT NOT NULL REFERENCES drafts(id), version INTEGER NOT NULL, text TEXT NOT NULL, author TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, UNIQUE(draft_id, version));
CREATE TABLE approvals (id TEXT PRIMARY KEY, draft_id TEXT NOT NULL REFERENCES drafts(id), draft_version INTEGER NOT NULL, conversation_revision INTEGER NOT NULL, approved_by TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE delivery_attempts (id TEXT PRIMARY KEY, draft_id TEXT NOT NULL REFERENCES drafts(id), draft_version INTEGER NOT NULL, channel TEXT NOT NULL, recipient TEXT NOT NULL, status TEXT NOT NULL, external_id TEXT, error TEXT, created_at TEXT NOT NULL, finished_at TEXT);
CREATE TABLE outcome_events (id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES persons(id), conversation_id TEXT NOT NULL REFERENCES conversations(id), kind TEXT NOT NULL, evidence TEXT NOT NULL, source_message_id TEXT REFERENCES messages(id), draft_id TEXT REFERENCES drafts(id), value REAL, author TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE lessons (id TEXT PRIMARY KEY, partner_id TEXT NOT NULL REFERENCES partners(id), conversation_id TEXT REFERENCES conversations(id), title TEXT NOT NULL, text TEXT NOT NULL, applicability TEXT NOT NULL, evidence TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'candidate', author TEXT NOT NULL, run_id TEXT, created_at TEXT NOT NULL, reviewed_at TEXT);
CREATE TABLE capability_proposals (id TEXT PRIMARY KEY, partner_id TEXT NOT NULL REFERENCES partners(id), name TEXT NOT NULL, purpose TEXT NOT NULL, permissions_json TEXT NOT NULL, acceptance TEXT NOT NULL, skill_content TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'proposed', author TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE skill_versions (id TEXT PRIMARY KEY, proposal_id TEXT NOT NULL REFERENCES capability_proposals(id), name TEXT NOT NULL, version INTEGER NOT NULL, content TEXT NOT NULL, sha256 TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', reviewed_by TEXT, created_at TEXT NOT NULL, UNIQUE(name,version));
CREATE TABLE events (id INTEGER PRIMARY KEY AUTOINCREMENT, partner_id TEXT NOT NULL, conversation_id TEXT, kind TEXT NOT NULL, actor TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE command_receipts (id TEXT PRIMARY KEY, fingerprint TEXT NOT NULL, result_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE channel_offsets (channel TEXT NOT NULL, account_id TEXT NOT NULL, cursor TEXT NOT NULL, PRIMARY KEY(channel,account_id));
CREATE TABLE tool_calls (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), name TEXT NOT NULL, arguments_json TEXT NOT NULL, result_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE VIRTUAL TABLE lessons_fts USING fts5(title,text,applicability,content='lessons',content_rowid='rowid');
CREATE TRIGGER lessons_ai AFTER INSERT ON lessons BEGIN INSERT INTO lessons_fts(rowid,title,text,applicability) VALUES(new.rowid,new.title,new.text,new.applicability); END;
CREATE TRIGGER lessons_ad AFTER DELETE ON lessons BEGIN INSERT INTO lessons_fts(lessons_fts,rowid,title,text,applicability) VALUES('delete',old.rowid,old.title,old.text,old.applicability); END;
CREATE TRIGGER lessons_au AFTER UPDATE ON lessons BEGIN INSERT INTO lessons_fts(lessons_fts,rowid,title,text,applicability) VALUES('delete',old.rowid,old.title,old.text,old.applicability); INSERT INTO lessons_fts(rowid,title,text,applicability) VALUES(new.rowid,new.title,new.text,new.applicability); END;
